
   function showAbout(){
    var screen = document.getElementById('screen');
    screen.classList.add('show-about');
    var about = screen.querySelector('.page-about');
    about.scrollTop = 0;
  }
  function showProjetos(){
    var screen = document.getElementById('screen');
    screen.classList.add('show-projetos');
    var projetos = screen.querySelector('.page-projetos');
    projetos.scrollTop = 0;
  }
  
  function abrirProjetoDetalhes(id, titulo, badges, imagem, descricao, duracao, data, papel, problema, solucao){
    var screen = document.getElementById('screen');
    screen.classList.add('show-projeto-detalhes');
    
    // Preencher dados
    document.getElementById('projetoTitulo').textContent = titulo;
    document.getElementById('projetoBadge1').textContent = badges[0] || '';
    document.getElementById('projetoBadge2').textContent = badges[1] || '';
    document.getElementById('projetoImagem').src = imagem;
    document.getElementById('projetoImagem').alt = 'Prévia do projeto ' + titulo;
    document.getElementById('projetoDescricao').textContent = descricao;
    
    // Formatar duração
    var duraçãoParts = duracao.split(' ');
    if(duraçãoParts.length > 1){
      document.getElementById('projetoDuracao').innerHTML = duraçãoParts[0] + '<br>' + duraçãoParts.slice(1).join(' ');
    } else {
      document.getElementById('projetoDuracao').innerHTML = duracao + '<br>Meses';
    }
    
    document.getElementById('projetoData').textContent = data;
    document.getElementById('projetoPapel').innerHTML = papel.replace(/ /g, '<br>');
    document.getElementById('projetoProblema').textContent = problema;
    document.getElementById('projetoSolucao').textContent = solucao;
    
    // Mostrar botão de documentação apenas para SkillUp e MeuNutri
    var docBtn = document.getElementById('verDocBtn');
    if(id === 'skillup' || id === 'meunutri'){
      docBtn.textContent = 'Ver Documentação';
      docBtn.style.display = 'block';
      window.projetoAtualId = id;
    } else if(id === 'portfolio'){
      docBtn.textContent = 'Ver Projeto';
      docBtn.style.display = 'block';
      window.projetoAtualId = id;
    } else {
      docBtn.style.display = 'none';
    }
    
    var detalhes = screen.querySelector('.page-projeto-detalhes');
    detalhes.scrollTop = 0;
  }
  
  function voltarProjetos(){
    var screen = document.getElementById('screen');
    screen.classList.remove('show-projeto-detalhes');
    var projetos = screen.querySelector('.page-projetos');
    projetos.scrollTop = 0;
  }
  
  function compartilharProjeto(){
    if(navigator.share){
      navigator.share({
        title: document.getElementById('projetoTitulo').textContent,
        text: document.getElementById('projetoDescricao').textContent,
        url: window.location.href
      }).catch(err => console.log('Erro ao compartilhar:', err));
    } else {
      alert('Compartilhamento não suportado neste navegador.');
    }
  }
  
  function abrirDocumentacao(){
    var id = window.projetoAtualId;
    
    if(id === 'skillup'){
      // Baixar PDF do SkillUp
      var link = document.createElement('a');
      link.href = 'Case_study_UIUX__1_.pdf';
      link.download = 'SkillUp_Case_Study_UI_UX.pdf';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } else if(id === 'meunutri'){
      // Baixar PDF do MeuNutri
      var link = document.createElement('a');
      link.href = 'MeuNutri.pdf';
      link.download = 'MeuNutri_Documentacao.pdf';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } else if(id === 'portfolio'){
      window.open('https://17062010.oneapp.dev/', '_blank');
    } else {
      alert('Link não disponível para este projeto.');
    }
  }
  
  function filtrarProjetos(cat, e){
    var chips = document.querySelectorAll('.filter-chip');
    chips.forEach(function(c){ c.classList.remove('active'); });
    if(e && e.currentTarget){ e.currentTarget.classList.add('active'); }
    var cards = document.querySelectorAll('.project-card');
    cards.forEach(function(card){
      if(cat === 'todos' || card.dataset.cat === cat){
        card.style.display = 'flex';
      } else {
        card.style.display = 'none';
      }
    });
  }
  function showHome(){
    var screen = document.getElementById('screen');
    screen.classList.remove('show-about');
    screen.classList.remove('show-projetos');
    var home = screen.querySelector('.page-home');
    home.scrollTop = 0;
    closeMenu();
  }
  function toggleMenu(){
    var btn = document.getElementById('menuBtn');
    var dropdown = document.getElementById('menuDropdown');
    var overlay = document.getElementById('menuOverlay');
    var isOpen = dropdown.classList.contains('open');
    if(isOpen){
      closeMenu();
    } else {
      btn.classList.add('open');
      dropdown.classList.add('open');
      overlay.classList.add('open');
    }
  }
  function closeMenu(){
    document.getElementById('menuBtn').classList.remove('open');
    document.getElementById('menuDropdown').classList.remove('open');
    document.getElementById('menuOverlay').classList.remove('open');
  }
  function scrollToSection(id){
    closeMenu();
    var target = document.getElementById(id);
    if(target){
      setTimeout(function(){
        target.scrollIntoView({behavior:'smooth', block:'start'});
        target.classList.add('menu-target-highlight');
        setTimeout(function(){
          target.classList.remove('menu-target-highlight');
        }, 900);
      }, 200);
    }
  }
