  function toggleCertificacoes(e){
    var extras = document.querySelectorAll('.cert-extra');
    var btn = document.getElementById('verMaisCertBtn');
    var aberto = extras.length && extras[0].style.display !== 'none';
    extras.forEach(function(el){
      el.style.display = aberto ? 'none' : 'flex';
    });
    btn.textContent = aberto ? 'Ver mais' : 'Ver menos';
  }
  function toggleIntro(e){
    var extra = document.getElementById('aboutIntroExtra');
    var btn = document.getElementById('verMaisIntroBtn');
    var aberto = extra.classList.contains('open');
    extra.classList.toggle('open', !aberto);
    btn.textContent = aberto ? 'Ver mais' : 'Ver menos';
  }
  var certificadoAtual = 'uiux';
  function baixarCertificado(){
    var c = certificados[certificadoAtual];
    var link = document.createElement('a');
    link.href = c.imagem;
    link.download = c.download;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
  function abrirCertificado(id){
    certificadoAtual = id;
    var c = certificados[id];
    document.getElementById('certModalTitle').textContent = c.titulo;
    var img = document.getElementById('certModalImg');
    img.src = c.imagem;
    img.alt = 'Certificado de ' + c.titulo;
    document.getElementById('certModal').classList.add('open');
  }
  function fecharCertificado(){
    if(document.fullscreenElement){ document.exitFullscreen(); }
    document.getElementById('certModal').classList.remove('open');
  }
  function toggleFullscreenCert(){
    var inner = document.getElementById('certModalInner');
    if(!document.fullscreenElement){
      if(inner.requestFullscreen){ inner.requestFullscreen(); }
    } else {
      document.exitFullscreen();
    }
  }
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape'){
      var modal = document.getElementById('certModal');
      if(modal.classList.contains('open')){ fecharCertificado(); }
      var dropdown = document.getElementById('menuDropdown');
      if(dropdown && dropdown.classList.contains('open')){ closeMenu(); }
    }
  });
  (function(){
    emailjs.init({ publicKey: "6Rr5wYsg0XF96x6sh" });
  })();

  var contactForm = document.getElementById('contactForm');
  var contactSubmitBtn = document.getElementById('contactSubmitBtn');
  var contactFormStatus = document.getElementById('contactFormStatus');

  contactForm.addEventListener('submit', function(e){
    e.preventDefault();
    contactSubmitBtn.disabled = true;
    contactSubmitBtn.textContent = 'Enviando...';
    contactFormStatus.textContent = '';

    contactForm.time.value = new Date().toLocaleString('pt-BR', {
      day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit'
    });

    emailjs.sendForm('service_v48qjvi', 'template_a4kb3sm', contactForm)
      .then(function(){
        contactFormStatus.style.color = '#4caf50';
        contactFormStatus.textContent = 'Mensagem enviada com sucesso!';
        contactForm.reset();
      })
      .catch(function(err){
        contactFormStatus.style.color = '#ff5c5c';
        contactFormStatus.textContent = 'Erro ao enviar. Tente novamente.';
        console.error('Erro EmailJS:', err);
      })
      .finally(function(){
        contactSubmitBtn.disabled = false;
        contactSubmitBtn.textContent = 'Submit';
      });
  });

  function baixarCurriculo(){
    var pdfB64 = '';
    var byteCharacters = atob(pdfB64);
    var byteNumbers = new Array(byteCharacters.length);
    for (var i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    var byteArray = new Uint8Array(byteNumbers);
    var blob = new Blob([byteArray], {type: 'application/pdf'});
    var url = URL.createObjectURL(blob);
    var link = document.createElement('a');
    link.href = url;
    link.download = 'Curriculo-Gabrielly-Maria.pdf';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }

